  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x1[i]);
  }
  POLYBENCH_DUMP_END("x1");

  POLYBENCH_DUMP_BEGIN("x2");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x2[i]);
  }
  POLYBENCH_DUMP_END("x2");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original semantics:
 *   x1 = x1 + A * y_1
 *   x2 = x2 + A^T * y_2
 *
 * Optimized implementation:
 *   1) Rewrite second product algebraically as
 *        x2[j] += sum_i A[i][j] * y_2[i]
 *      so that both use row-major access to A.
 *   2) Fuse both products so each A[i][j] load is reused:
 *        x1[i] += A[i][j] * y_1[j]
 *        x2[j] += A[i][j] * y_2[i]
 *   3) Apply 2D blocking and use small stack buffers:
 *        - x1_block[TI] keeps a tile of x1 in registers/L1
 *        - x2_block[TJ] accumulates contributions to a column tile
 *      This reduces global x2 traffic: each x2[j] is updated once
 *      per row-tile instead of once per row.
 *   4) Inner loops operate on contiguous data, enabling efficient
 *      vectorization by the compiler.
 */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, ii, jj;

  /* Tile sizes chosen to keep a TI x TJ tile of A (and the corresponding
     pieces of x1/x2/y_1/y_2) comfortably within L1 cache on typical CPUs. */
  enum { TILE_I = 32, TILE_J = 32 };

  /* Small stack buffers:
     - x1_block: holds a row tile of x1 so each element is loaded and
       stored only once per TILE_I rows.
     - x2_block: accumulates partial sums for a column tile so that
       global x2 is updated once per (row-tile, column-tile) instead of
       once per row. */
  DATA_TYPE x1_block[TILE_I];
  DATA_TYPE x2_block[TILE_J];

  /* Create restrict-qualified aliases to help the compiler with
     alias analysis and vectorization. */
  DATA_TYPE * __restrict__ x1p = x1;
  DATA_TYPE * __restrict__ x2p = x2;
  DATA_TYPE * __restrict__ y1p = y_1;
  DATA_TYPE * __restrict__ y2p = y_2;

#pragma scop
  /* Outer tiling over rows of A. Each ii-tile operates on a contiguous
     band of rows and the corresponding slice of x1. */
  for (ii = 0; ii < _PB_N; ii += TILE_I)
    {
      int i_end = ii + TILE_I;
      if (i_end > _PB_N)
        i_end = _PB_N;

      /* Load current x1 tile into a small buffer. This allows each
         x1[i] in the tile to stay in registers across all column tiles. */
      for (i = ii; i < i_end; ++i)
        x1_block[i - ii] = x1p[i];

      /* Tiling over columns of A / entries of x2. */
      for (jj = 0; jj < _PB_N; jj += TILE_J)
        {
          int j_end = jj + TILE_J;
          if (j_end > _PB_N)
            j_end = _PB_N;
          int j_block_size = j_end - jj;

          /* Initialize local accumulator for this x2 column tile. */
          for (j = 0; j < j_block_size; ++j)
            x2_block[j] = (DATA_TYPE)0;

          /* Process the TILE_I x TILE_J submatrix A[ii:i_end, jj:j_end]. */
          for (i = ii; i < i_end; ++i)
            {
              DATA_TYPE xi1 = x1_block[i - ii]; /* accumulator for x1[i] */
              DATA_TYPE y2_i = y2p[i];          /* reused across all j in this row */
              DATA_TYPE * __restrict__ Ai = &A[i][jj];

              /* Inner-most loop: contiguous in j for A, y_1, x2_block. */
              for (j = 0; j < j_block_size; ++j)
                {
                  DATA_TYPE aij = Ai[j];
                  xi1       += aij * y1p[jj + j]; /* part of x1 = x1 + A * y_1 */
                  x2_block[j] += aij * y2_i;      /* contributes to x2 = x2 + A^T * y_2 */
                }

              x1_block[i - ii] = xi1;
            }

          /* Commit the accumulated contributions for this column tile
             to the global x2 vector. Each x2[j] element is updated once
             per row-tile instead of once per row, reducing memory traffic. */
          for (j = 0; j < j_block_size; ++j)
            x2p[jj + j] += x2_block[j];
        }

      /* Write back the updated x1 tile. At this point x1_block contains
         the full contribution from all columns for rows [ii, i_end). */
      for (i = ii; i < i_end; ++i)
        x1p[i] = x1_block[i - ii];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_mvt (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x1), POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

