  {
    /* Register accumulators for this row.
       xi accumulates the full dot product for x1[i],
       y2_i is reused for all columns j of this row. */
    DATA_TYPE xi   = x1[i];
    DATA_TYPE y2_i = y_2[i];

    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE Aij = A[i][j];
