/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* The original kernel performs two matrix–vector products:
   *
   *   x1[i] += sum_j A[i][j] * y_1[j]
   *   x2[i] += sum_j A[j][i] * y_2[j]
   *
   * The second one is x2 = x2 + A^T * y_2, but it accesses A by columns
   * (A[j][i]), which is cache-unfriendly for a row-major layout.
   *
   * We rewrite the second product using an equivalent index form:
   *
   *   x2[j] += sum_i A[i][j] * y_2[i]
   *
   * (just a renaming of dummy indices i <-> j; both run over [0, n).)
   *
   * This allows us to fuse the two products into a single traversal:
   *
   *   for all (i, j):
   *     x1[i] += A[i][j] * y_1[j];
   *     x2[j] += A[i][j] * y_2[i];
   *
   * so each A[i][j] is loaded once, and both updates use row-major
   * accesses. x1[i] and y_2[i] are promoted to scalars per row to
   * reduce memory traffic. This transformation is mathematically
   * equivalent to the original kernel for all N.
   */

  /* Create local restrict-qualified aliases to help the compiler
   * reason about aliasing and enable better vectorization. The
   * PolyBench harness never passes overlapping arrays here. */
  DATA_TYPE *restrict x1_ = x1;
  DATA_TYPE *restrict x2_ = x2;
  DATA_TYPE *restrict y1_ = y_1;
  DATA_TYPE *restrict y2_ = y_2;
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++)
  {
    /* Per-row accumulators kept in registers. */
    DATA_TYPE xi1 = x1_[i];   /* accumulator for x1[i] */
    DATA_TYPE y2_i = y2_[i];  /* reused across all j for this row */

    DATA_TYPE *restrict A_row = A_[i];

    /* Inner loop walks j (columns) in the contiguous dimension,
     * giving good spatial locality for A_row[j], y1_[j], and x2_[j].
     * The compiler can vectorize this loop efficiently. */
    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE a_ij = A_row[j];
      xi1        += a_ij * y1_[j];  /* contribution to x1[i]      */
      x2_[j]     += a_ij * y2_i;    /* contribution to x2[j] (A^T) */
    }

    x1_[i] = xi1;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2, DATA_TYPE, N, n);
