/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_mvt[[gnu::flatten, gnu::noinline]](int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /*
   * Optimized version of the original kernel.
   *
   * Original code:
   *   // x1 <- x1 + A * y_1
   *   for i
   *     for j
   *       x1[i] += A[i][j] * y_1[j];
   *
   *   // x2 <- x2 + A^T * y_2
   *   for i
   *     for j
   *       x2[i] += A[j][i] * y_2[j];
   *
   * We first rewrite the second product algebraically as:
   *
   *   x2[j] += sum_i A[i][j] * y_2[i];
   *
   * which is the same operation with the dummy indices (i,j) swapped.
   * After this rewrite, both updates use A[i][j] in row-major order.
   *
   * We then fuse the two matrix–vector products so that each A[i][j]
   * load contributes to both x1[i] and x2[j]:
   *
   *   for i:
   *     for j:
   *       x1[i] += A[i][j] * y_1[j];
   *       x2[j] += A[i][j] * y_2[i];
   *
   * This preserves the mathematical results while roughly halving the
   * number of matrix loads and improving cache locality.
   *
   * Finally, we tile the i and j loops and keep frequently used scalars
   * (x1[i], y_2[i]) in registers to improve temporal locality and make
   * the innermost loop friendly to auto-vectorization.
   */

